'use strict';
/* ===== automated QA driver ===== */
window.__fails = [];
window.addEventListener('error', e => { window.__fails.push('uncaught: ' + e.message); console.error('UNCAUGHT ' + e.message); });
function OK(name, cond) { console.log((cond ? 'PASS ' : 'FAIL ') + name); if (!cond) window.__fails.push(name); }
const Q = { phase: 0, t: 0, boss: null, picked: 0, log: [] };

const PHASES = [];
function phase(n, fn) { PHASES.push({ n, fn }); }

/* autopilot dialog advancing */
function autoDlg(pickHint) {
  if (G.mode !== 'dialog') return false;
  if (Dlg._ch && Dlg._ch.length) {
    let idx = 0;
    if (pickHint) for (let i = 0; i < Dlg._ch.length; i++) if (pickHint.test(Dlg._ch[i].t)) { idx = i; break; }
    Dlg.pick(idx); return true;
  }
  if (Dlg.typing) { Dlg.shown = Dlg.full; Dlg.typing = false; $('dlgText').textContent = Dlg.full; }
  Dlg.next(); return true;
}
function autoMenu() { if (G.mode === 'menu' && G.panel === 'shop') return true; return false; }
/* spawn & fell a boss via real combat path, then autopilot the after-scene */
function fightBoss(key) {
  if (!G.boss) { spawnBoss(key, G.p.x + 60, G.p.y); return false; }
  G.p.hp = G.p.maxhp;
  hurtMob(G.boss); hurtMob(G.boss);
  return true;
}

const ST = {};
let step = 0, phaseName = '';
function nextPhase() {
  if (step < PHASES.length) { const p = PHASES[step++]; phaseName = p.n; console.log('PHASE ' + p.n); return p.fn; }
  return null;
}
const waits = {}; // phase -> number of ticks to wait
function W(n) { waits[phaseName] = n; }

PHASES.push = function (o) { Array.prototype.push.call(this, o); };

/* ---- phase list ---- */
phase('boot', () => { ST.chapChk = [];

  if (G.mode !== 'title') { W(5); return; }
  Game.newGame(); W(3);
});
phase('prologue', () => { // autopilot prologue dialogue + sanity checks after
  if (autoDlg()) return;
  if (G.mode !== 'play') { W(3); return; }
  OK('chapter is 1 after prologue', G.chapter === 1);
  OK('dawn quest done', G.quests.dawn && G.quests.dawn.done);
  OK('rusty blade equipped', G.p.wpn === 'rusty');
  OK('ch1 quest added', !!G.quests.ch1);
  G.p.coins = 500; // QA budget
  Q.next = 'npcLoop'; ST.npcI = 0;
});
const NPCS = ['mara', 'rowan', 'ott', 'bruna', 'pip', 'villager', 'nima', 'hesan', 'zia', 'mav', 'hermit', 'spirit', 'rocco'];
phase('npcLoop', () => {
  if (G.mode === 'menu') { // shop opened by ott/bruna — buy & leave
    if (G.panel === 'shop') {
      const price = G.p.coins >= 40 ? 40 : 0;
      if (price && !ST.bought) { const n0 = G.p.bag.pot_s || 0; buyItem('pot_s', price); OK('shop purchase adds potion', (G.p.bag.pot_s || 0) > n0); ST.bought = true; }
      Menus.close(); ST.bought = false; ST.npcI++; return;
    }
    return;
  }
  if (autoDlg()) return;
  const k = NPCS[ST.npcI];
  if (!k) { Q.next = 'questLoop'; return; }
  Dlg.run(k); ST.cur = k;
  if (ST.npcI === 2 && G.mode === 'menu') { ST.npcI++; } // ott opened shop directly (mode=menu, dlg closed)
});
phase('questLoop', () => {
  if (autoDlg()) return;
  // side quest wiring checks
  Dlg.run('pip'); // q_well offered choice
  addQuest('q_tea'); giveItem('moonpetal', 3);
  Dlg.run('rowan');
  if (G.quests.q_tea && G.quests.q_tea.done) OK('q_tea complete via rowan', true); else OK('q_tea turn-in', false);
  addQuest('q_lantern'); giveItem('childs_lantern', 1); Dlg.run('nima');
  OK('q_lantern done + lantern charm', G.quests.q_lantern.done && G.p.ownC.includes('lantern'));
  addQuest('q_remedy'); giveItem('pollen', 2); giveItem('moss', 1); Dlg.run('hesan');
  OK('q_remedy done', G.quests.q_remedy.done);
  addQuest('q_ghost'); Dlg.run('spirit'); Dlg.pick(0); // starts _spirit2 chain... autopick via autoDlg
  addQuest('q_toll'); advanceQuest('q_toll'); G.p.coins += 40; Dlg.run('mara');
  Q.next = 'wellWell';
});
phase('wellWell', () => {
  if (autoDlg()) return;
  G.p.coins += 50;
  const map = G.mapObj, key = '109,45';
  const t = map.tags[key];
  openChestShim(t, 'well');
  Q.next = 'saves';
});
function openChestShim(t, kind) { // reuse well/well2 via direct flow
  if (kind === 'well') { GAME włWell(); }
}
function GAME_wellWell() {}
